def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: int or None
    """
    if value is None:
        return None
    # Ensure the value is a timedelta-like object
    if not hasattr(value, "total_seconds"):
        return None
    try:
        # Convert the entire duration to an integer number of seconds
        return int(value.total_seconds())
    except Exception:
        return None

def index(self, key):
    """ Return the index of the given item.
    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        if self._sort:
            return sorted_index(self._index, key)
        return self._index.index(key)
    except ValueError:
        # use KeyError for compatibility
        raise KeyError('Key {} not found'.format(key))

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine ordered field names
    field_names = None
    if hasattr(self, "_keys") and isinstance(getattr(self, "_keys", None), (list, tuple)):
        field_names = list(self._keys)
    elif hasattr(self, "_fields") and isinstance(getattr(self, "_fields", None), (list, tuple)):
        field_names = list(self._fields)
    else:
        field_names = [k for k in vars(self).keys() if not k.startswith("_")]

    get_value = lambda name: getattr(self, name, None)

    # If no keys provided, return all fields
    if not keys:
        return {name: get_value(name) for name in field_names}

    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(field_names):
                raise IndexError(f"Index {idx} out of bounds")
            name = field_names[idx]
        else:
            name = str(k)
        # Include the key even if it doesn't exist in the record
        result[name] = get_value(name) if name in field_names else None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Build the message payload
    msg = {
        "type": "DISCARD",
        "n": n,
        "qid": qid
    }

    # Include hooks if provided, serializing them into a form that can be sent
    if dehydration_hooks:
        # Store a representation of the hooks; actual serialization may be
        # handled elsewhere in the messaging system.
        msg["dehydration_hooks"] = {
            cls.__name__: hook.__name__ for cls, hook in dehydration_hooks.items()
        }

    if hydration_hooks:
        msg["hydration_hooks"] = {
            cls.__name__: hook.__name__ for cls, hook in hydration_hooks.items()
        }

    # Append the message to the output queue.  The exact queue attribute or
    # method may differ in real implementations; here we assume a protected
    # member named `_output_queue` that supports `append`.
    if hasattr(self, "_output_queue") and hasattr(self._output_queue, "append"):
        self._output_queue.append(msg)
    elif hasattr(self, "queue") and hasattr(self.queue, "append"):
        self.queue.append(msg)
    else:
        # Fallback: attempt to send via a generic send method
        send_method = getattr(self, "send", None)
        if callable(send_method):
            send_method(msg)
        else:
            raise AttributeError("No queue or send method available to enqueue DISCARD message")

    # Return a Response object that will handle the hooks provided by the caller
    try:
        response_class = getattr(self, "Response", Response)
    except NameError:
        # If Response is not defined in this context, use a simple placeholder
        class Response:  # pragma: no cover
            def __init__(self, **kw): self.handlers = kw
    return response_class(**handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    parts = s.split(".")
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # try to extract leading numeric portion
            num = ""
            for ch in part:
                if ch.isdigit():
                    num += ch
                else:
                    break
            if num:
                nums.append(int(num))
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorating_function(user_function):
        cache = {}
        order = []

        def _make_key(args, kwds, typed):
            key = args
            if kwds:
                items = tuple(sorted(kwds.items()))
                key += items
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in items)
            return key

        def wrapper(*args, **kwds):
            key = _make_key(args, kwds, typed)
            now = timer()
            if key in cache:
                value, ts = cache[key]
                if now - ts < ttl:
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # expired
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            result = user_function(*args, **kwds)
            cache[key] = (result, now)
            order.append(key)
            if len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result
        return wrapper
    return decorating_function

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = OrderedDict()

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # keyword arguments as sorted tuple of items
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include the type of each argument in the key
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            if maxsize == 0:
                # No caching
                return func(*args, **kwargs)

            key = _make_key(args, kwargs)
            if key in cache:
                # Mark as most recently used
                cache.move_to_end(key)
                return cache[key]

            # Compute the result and cache it
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the most recently used entry
                cache.popitem(last=True)
            cache[key] = result
            return result

        # expose the internal cache if desired
        wrapper.mru_cache = cache
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    return functools.lru_cache(maxsize=maxsize, typed=typed)

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}

        def wrapper(*args, **kwargs):
            # Build a key based on function arguments.
            if typed:
                key = (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(v) for v in args),
                    tuple(type(v) for _, v in sorted(kwargs.items())),
                )
            else:
                key = (args, tuple(sorted(kwargs.items())))
            # Check cache.
            if key in cache:
                freq[key] += 1
                return cache[key]
            # Compute result and store in cache.
            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1
            # Evict if over size.
            if len(cache) > maxsize:
                # Find the lowest frequency.
                min_freq = min(freq.values())
                # Choose any key with that frequency.
                for k in list(freq.keys()):
                    if freq[k] == min_freq:
                        del cache[k]
                        del freq[k]
                        break
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=keys.hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
