                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def _reset_logging(cls):
    """Reset"""
    root_logger = logging.getLogger()
    for handler in root_logger.handlers[:]:
        root_logger.removeHandler(handler)

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    # Collect attributes defined directly on the interface class
    members = {
        name: value
        for name, value in self.__class__.__dict__.items()
        if not inspect.isroutine(value) and not (name.startswith("__") and name.endswith("__"))
    }

    result = {}
    for name, value in members.items():
        if not all and name.startswith("_"):
            continue

        description = ""

        # Prefer a custom 'description' attribute if present
        if hasattr(value, "description"):
            description = value.description
        # Fallback to the docstring of the attribute itself
        if not description and hasattr(value, "__doc__"):
            doctxt = value.__doc__
            if doctxt:
                description = doctxt.strip().splitlines()[0]
        # For descriptors like property, try to get the docstring of the getter
        if not description and isinstance(value, property):
            if value.fget and value.fget.__doc__:
                description = value.fget.__doc__.strip().splitlines()[0]

        result[name] = description

    return result

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    attrs = []
    classes = (self.__class__,) if not all else self.__class__.__mro__
    for cls in classes:
        for name, val in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(val):
                continue
            attrs.append(name)
    return sorted(set(attrs))

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return not _c_optimizations_required()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If it's a single FillRequest element
    if isinstance(seq, FillRequest):
        return True

    # If it's a Source sequence, we reject
    if isinstance(seq, Source):
        return False

    # If it's not iterable or is a string/bytes, cannot be
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Check each element
    for item in iterator:
        if isinstance(item, FillRequest):
            return True

    return False

