def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord = np.asarray(coord)
    # If coord has more than one dimension, treat each row as a point
    if coord.ndim == 1:
        points = [coord]
    else:
        points = coord

    for pt in points:
        # build a list of bin indices for each dimension
        indices = []
        for dim, edge in enumerate(self.edges):
            # find the rightmost bin edge less than or equal to the coordinate
            i = np.searchsorted(edge, pt[dim], side='right') - 1
            # ignore points outside histogram range
            if i < 0 or i >= self.hist.shape[dim]:
                break
            indices.append(i)
        else:
            # only update if all dimensions are inside bounds
            self.hist[tuple(indices)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            if not LABEL_KEY_RE.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value
        if isinstance(value, list):
            # The list itself is not an acceptable value type.
            errors.append(
                {repr(value): "expected string or bytes-like object"}
            )
            # Validate each element inside the list
            for elem in value:
                if not isinstance(elem, str):
                    errors.append(
                        {repr(elem): "expected string or bytes-like object"}
                    )
                else:
                    if not LABEL_VALUE_RE.match(elem):
                        errors.append(
                            {
                                repr(elem): f"Label value '{elem}' does not match the regex [...]"
                            }
                        )
        else:
            if not isinstance(value, str):
                errors.append(
                    {repr(value): "expected string or bytes-like object"}
                )
            else:
                if not LABEL_VALUE_RE.match(value):
                    errors.append(
                        {
                            repr(value): f"Label value '{value}' does not match the regex [...]"
                        }
                    )

    if errors:
        raise ValidationError(errors)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        path = path_exists(path, force_run=True)
    except Exception:
        return False
    if not os.path.isdir(path):
        return False
    if os.path.isdir(os.path.join(path, '.pyfs')):
        return True
    if os.path.isdir(os.path.join(path, '.ocfl')) and os.path.isdir(os.path.join(path, 'objects')):
        return True
    return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    return prefix + str(self.status)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If the object has a `log` attribute (a list or iterable of strings),
    # generate a string representation by prepending the prefix to each line.
    log = getattr(self, "log", None)
    if not log:
        return prefix
    return "\n".join(f"{prefix}{line}" for line in log)

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same validation type
    if not isinstance(prior, type(self)):
        raise TypeError(f'prior must be an {type(self).__name__} instance, got {type(prior).__name__}')

    # Compare basic inventory identifiers if available
    try:
        self_id = self.inventory.id
        prior_id = prior.inventory.id
        if self_id != prior_id:
            raise ValueError(f'Inventory IDs do not match: {self_id!r} vs {prior_id!r}')
    except AttributeError:
        # If no explicit id, fall back to comparing inventory objects directly
        if getattr(self, 'inventory', None) != getattr(prior, 'inventory', None):
            raise ValueError('Inventories do not match between current and prior objects')

    # Ensure version ordering (assume a numeric or comparable version attribute)
    try:
        if getattr(self, 'version', 0) <= getattr(prior, 'version', 0):
            raise ValueError(f'Current version ({getattr(self, "version", None)}) must be greater than prior version ({getattr(prior, "version", None)})')
    except AttributeError:
        # If no version attribute, the validation cannot be performed
        pass

    # Verify that all entries present in the prior inventory are also present in the current one
    try:
        prior_keys = set(prior.inventory.keys())
        current_keys = set(self.inventory.keys())
        missing = prior_keys - current_keys
        if missing:
            raise ValueError(f'Current inventory is missing keys from prior inventory: {sorted(missing)!r}')
    except AttributeError:
        # If inventory does not support keys(), skip this check
        pass

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    # Helper to parse and compare version strings
    try:
        from distutils.version import LooseVersion
        def v_key(v):
            return LooseVersion(v)
    except Exception:
        def v_key(v):
            return v

    mapping = defaultdict(set)

    # Helper to extract attributes from a record
    def _get(rec, attr):
        if isinstance(rec, dict):
            return rec.get(attr)
        return getattr(rec, attr, None)

    # Case 1: inventory is a dict where keys are logical paths
    if isinstance(inventory, dict):
        # Check if values appear to be version maps or direct file sets
        val0 = next(iter(inventory.values()), None)
        if isinstance(val0, dict):
            # mapping: logical_path -> {version: set(files)}
            for logical_path, ver_map in inventory.items():
                files = ver_map.get(version, set())
                mapping[logical_path].update(files)
            # Include duplicates from later versions
            for logical_path, ver_map in inventory.items():
                for ver, files in ver_map.items():
                    try:
                        if v_key(ver) > v_key(version):
                            if logical_path in mapping:
                                mapping[logical_path].update(files)
                    except Exception:
                        continue
            return dict(mapping)

        # Check if values are file sets for this version
        if isinstance(val0, (set, list, tuple)):
            for logical_path, files in inventory.items():
                mapping[logical_path].update(files)
            return dict(mapping)

        # Handle nested dicts that might map to different attribute fields
        for logical_path, val in inventory.items():
            if isinstance(val, dict):
                files = val.get(version, set())
                if isinstance(files, (set, list, tuple)):
                    mapping[logical_path].update(files)
        return dict(mapping)

    # Case 2: inventory is an iterable of records (dict or object)
    # Build mapping for the exact version first
    for rec in inventory:
        rec_ver = _get(rec, 'version')
        logical_path = _get(rec, 'logical_path')
        content_file = _get(rec, 'content_file')
        if rec_ver is None or logical_path is None or content_file is None:
            continue
        if rec_ver == version:
            mapping[logical_path].add(content_file)

    # Include duplicates from later versions for the same logical paths
    for rec in inventory:
        rec_ver = _get(rec, 'version')
        logical_path = _get(rec, 'logical_path')
        content_file = _get(rec, 'content_file')
        if rec_ver is None or logical_path is None or content_file is None:
            continue
        try:
            if v_key(rec_ver) > v_key(version) and logical_path in mapping:
                mapping[logical_path].add(content_file)
        except Exception:
            pass

    return dict(mapping)

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError('Fixity block must be a dictionary')

        # The expected key holding file entries
        if 'files' not in fixity:
            raise ValueError('Missing required "files" key in fixity block')

        files = fixity['files']
        if not isinstance(files, list):
            raise ValueError('"files" must be a list of file entries')

        # Convert manifest files into a set of valid paths
        manifest_set = set(manifest_files)

        seen_paths = set()
        for idx, entry in enumerate(files):
            if not isinstance(entry, dict):
                raise ValueError(f'File entry #{idx} must be a dictionary')

            if 'path' not in entry:
                raise ValueError(f'Missing "path" in file entry #{idx}')

            path = entry['path']
            if path not in manifest_set:
                raise ValueError(f'File "{path}" in fixity not found in manifest')

            if path in seen_paths:
                raise ValueError(f'Duplicate reference to file "{path}" in fixity')
            seen_paths.add(path)

            # Optional: basic validation of hash and algorithm fields
            if 'hash' not in entry or not isinstance(entry['hash'], str) or not entry['hash']:
                raise ValueError(f'Invalid or missing "hash" for file "{path}"')

            if 'algorithm' in entry and not isinstance(entry['algorithm'], str):
                raise ValueError(f'Invalid "algorithm" for file "{path}"')

        return True

def files_list(path):
    """Return the files in `path`"""
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except OSError:
        return []

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        # Try XPath query if the node supports it
        try:
            if hasattr(node, 'xpath'):
                matches = node.xpath(xpath)
                if matches:
                    return matches[0]
            # Fall back to CSS selector if available
            if hasattr(node, 'select'):
                matches = node.select(xpath)
                if matches:
                    return matches[0]
        except Exception:
            continue
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        with open(VERSION_PATH, 'r') as rfile:
            contents = rfile.read().strip()
        _, version = contents.split('=')
        version = version.strip().strip('"\'')

        return {'version': version, 'status': 'ok'}
    except Exception:
        return {'version': 'unknown', 'status': 'default'}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Ensure pieces is iterable of strings
    if not hasattr(pieces, '__iter__'):
        raise TypeError('pieces must be an iterable of strings')
    # Combine all pieces into a single string
    content = ''.join(str(p) for p in pieces)
    # Apply requested style
    if style == 'uppercase':
        return content.upper()
    elif style == 'lowercase':
        return content.lower()
    elif style == 'reverse':
        return content[::-1]
    else:
        # Default: return the plain joined content
        return content

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        cmd.extend(args)
    if verbose:
        print(f"Running command: {' '.join(cmd)}")
    # If hide_stderr is True we redirect stderr to stdout, otherwise let it pass through
    stderr_pipe = subprocess.PIPE if hide_stderr else None
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_pipe,
            env=env,
            check=True,
            text=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        error_msg = f"Command '{' '.join(cmd)}' returned non‑zero exit status {exc.returncode}"
        if exc.stderr:
            error_msg += f"\nError output: {exc.stderr}"
        raise subprocess.CalledProcessError(exc.returncode, exc.cmd, output=exc.stdout, stderr=exc.stderr) from None

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    # Determine the root directory to walk; assume it is stored in self.storage_root or self.root
    root = getattr(self, 'storage_root', None) or getattr(self, 'root', None)
    if not root or not isinstance(root, str):
        if show_warnings:
            print("Storage root not defined or is not a string.")
        return 0, 0

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            is_valid = True

            # Validate the object itself (e.g., file exists and is readable)
            if validate_objects:
                try:
                    with open(file_path, 'rb') as f:
                        data = f.read()
                    if not data:
                        is_valid = False
                        if show_warnings:
                            print(f"Empty file detected: {file_path}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Could not read file {file_path}: {exc}")

            # Check digest if requested
            if is_valid and check_digests:
                digest_file = f"{file_path}.md5"
                if os.path.exists(digest_file):
                    try:
                        with open(digest_file, 'r') as df:
                            expected_digest = df.read().strip()
                        with open(file_path, 'rb') as f:
                            actual_digest = hashlib.md5(f.read()).hexdigest()
                        if actual_digest != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {file_path}")
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            print(f"Error validating digest for {file_path}: {exc}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ''
    parts = version.split('.')
    widths = [len(p) for p in parts]
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any part is not purely numeric, return the original version unchanged
        return version
    # Increment the last part
    nums[-1] += 1
    formatted = []
    for num, width, orig in zip(nums, widths, parts):
        if orig.startswith('0') and width > 1:
            formatted.append(str(num).zfill(width))
        else:
            formatted.append(str(num))
    return '.'.join(formatted)

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f"path does not exist: {path}"
    if os.path.isfile(path):
        return "file"
    if os.path.isdir(path):
        try:
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    return "object"
            return "root"
        except Exception as exc:
            return f"error accessing directory: {exc}"
    return f"unknown path type: {path}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params

    Ensures the params dictionary contains the correct ``ids`` key for
    operations that target one or more Bugzilla bugs. If ``bug_ids`` is a
    single integer it is converted to a string; if it is an iterable,
    the values are joined with commas. Existing ids will be merged.

    Returns the amended dictionary.
    """
    if not bug_ids:
        return params

    # Normalise bug_ids to a comma separated string
    if isinstance(bug_ids, (str, bytes)):
        ids_string = bug_ids
    else:
        try:
            iter(bug_ids)
        except TypeError:
            ids_string = str(bug_ids)
        else:
            ids_string = ",".join(str(b) for b in bug_ids)

    # Merge with any existing ids in params
    if "ids" in params:
        if isinstance(params["ids"], str):
            params["ids"] = f"{params['ids']},{ids_string}"
        else:
            # Convert to list of strings and merge
            existing = [str(x) for x in params["ids"]]
            params["ids"] = ",{0}".format(ids_string)  # add new ids
            params["ids"] = ",".join(existing + [ids_string])
    else:
        params["ids"] = ids_string

    # Bugzilla uses `ids` for multiple bugs; remove any stray `id`
    params.pop("id", None)

    return params

